 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    out = [row[:] for row in grid]
    seeds = []
    # A diagonal pair of the same non-background color defines a ray.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    seeds.append((r, c, dr, dc, color))
    for r, c, dr, dc, color in seeds:
        # Extend outward from both ends of the matching diagonal pair.
        for sr, sc, step_r, step_c in ((r, c, -dr, -dc), (r + dr, c + dc, dr, dc)):
            rr, cc = sr + step_r, sc + step_c
            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                out[rr][cc] = color
                rr += step_r
                cc += step_c
    return out
